{
  "name": "opencode-lazy",
  "version": "0.2.2",
  "description": "Plugin manager for OpenCode. Search, install, and manage plugins without leaving your session.",
  "keywords": [
    "lazy",
    "opencode",
    "opencode-plugin",
    "package-manager",
    "plugin-manager"
  ],
  "homepage": "https://github.com/griffinmartin/opencode-lazy#readme",
  "bugs": {
    "url": "https://github.com/griffinmartin/opencode-lazy/issues"
  },
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/griffinmartin/opencode-lazy.git"
  },
  "files": [
    "opencode-lazy.js",
    "dist"
  ],
  "type": "module",
  "main": "opencode-lazy.js",
  "module": "opencode-lazy.js",
  "types": "dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./opencode-lazy.js"
    },
    "./opencode-lazy": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    },
    "./opencode-lazy.js": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    }
  },
  "dependencies": {
    "jsonc-parser": "^3.3.1"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "latest",
    "@types/node": "^25.5.0",
    "oxfmt": "0.41.0",
    "oxlint": "1.56.0",
    "typescript": "^5.0.0"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": "*"
  },
  "scripts": {
    "build": "tsc",
    "test": "node --test --experimental-strip-types src/**/*.test.ts",
    "lint": "oxlint && oxfmt --check .",
    "lint:fix": "oxlint --fix . && oxfmt --write .",
    "format": "oxfmt --write ."
  }
}
